package io.github.lucf15.tiffrenderer

import android.os.ParcelFileDescriptor
import android.util.Base64
import androidx.test.platform.app.InstrumentationRegistry
import java.io.File
import java.io.FileOutputStream

/**
 * Test fixtures embedded as base64 rather than `src/androidDeviceTest/assets` files: this
 * module's Gradle plugin (`com.android.kotlin.multiplatform.library`) doesn't merge that
 * directory the way classic AGP merges `src/androidTest/assets` for a plain `com.android.library`
 * module. Generated by `lib/core/src/androidDeviceTest/tools/generate_fixtures.py`; see
 * that script if a fixture needs regenerating, then re-run the base64 dump against its output.
 */
internal object TestFixtures {
    private val encoded = mapOf(
        "huge_dimensions.tif" to
            "SUkqAAgAAAAJAAABBAABAAAAoIYBAAEBBAABAAAAoIYBAAIBAwABAAAACAAAAAMBAwABAAAAAQAAAAYBAwABAAAAAQAAABEBBAABAAAAegAAABUBAwABAAAAAQAAABYBBAABAAAAoIYBABcBBAABAAAADAAAAAAAAAD///////////////8=",
        "not_a_tiff.bin" to
            "",
        "rgba_associated_alpha.tif" to
            "",
        "single_page_rgb.tif" to
            "",
        "supported_ccittg4.tif" to
            "",
        "supported_deflate.tif" to
            "",
        "supported_jpeg.tif" to
            "",
        "supported_lzw.tif" to
            "",
        "supported_packbits.tif" to
            "",
        "supported_uncompressed.tif" to
            "",
        "supported_webp.tif" to
            "",
        "truncated.tif" to
            "",
        "unsupported_lerc.tif" to
            "",
        "unsupported_lzma.tif" to
            "",
        "unsupported_zstd.tif" to
            "",
        "varying_page_dimensions.tif" to
            "",
    )

    fun open(name: String): ParcelFileDescriptor {
        val bytes = Base64.decode(encoded.getValue(name), Base64.DEFAULT)
        val targetContext = InstrumentationRegistry.getInstrumentation().targetContext
        val copy = File(targetContext.cacheDir, name)
        FileOutputStream(copy).use { it.write(bytes) }
        return ParcelFileDescriptor.open(copy, ParcelFileDescriptor.MODE_READ_ONLY)
    }
}
